import { test, expect } from '@playwright/test';

test.describe('Navigate to Home Page by Clicking Logo', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should navigate to home page when logo is clicked', async ({ page }) => {
    // Verify user is on dashboard page
    const pageTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(pageTitle).toBeVisible();

    // Click the logo to navigate to home page
    const logo = page.getByRole('img', { name: /logo/i });
    await expect(logo).toBeVisible();
    await logo.click();

    // Verify navigation to home page
    const homePageTitle = page.getByRole('heading', { name: /home/i });
    await expect(homePageTitle).toBeVisible();

    // Verify home page content is displayed
    const welcomeMessage = page.getByText(/welcome back/i);
    await expect(welcomeMessage).toBeVisible();
  });

  test('should handle logo click when logo is not visible', async ({ page }) => {
    // Intercept the logo element to simulate it not being present
    await page.route('**/logo', route => route.abort());

    // Verify dashboard page is visible
    const pageTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(pageTitle).toBeVisible();

    // Attempt to click the logo (should not be found)
    const logo = page.getByRole('img', { name: /logo/i });
    const isLogoVisible = await logo.isVisible();
    expect(isLogoVisible).toBeFalsy();

    // Verify user remains on dashboard page
    const dashboardContent = page.getByText(/dashboard overview/i);
    await expect(dashboardContent).toBeVisible();
  });
});
